vec3 calculateLJForce(const vec3& r, double epsilon, double sigma) {
    double dist = r.length();
    if (dist < 1e-10) {
        return vec3(0, 0, 0);
    }

    double sigma_over_r = sigma / dist;
    double sigma_over_r_6 = std::pow(sigma_over_r, 6);
    double sigma_over_r_12 = sigma_over_r_6 * sigma_over_r_6;

    double force_magnitude = 24.0 * epsilon / dist * (2.0 * sigma_over_r_12 - sigma_over_r_6);

    vec3 force_direction = r / dist;
    return force_magnitude * force_direction;
}

